/**
 * @summary Attach a project document
 */
export const attachProjectDocument = (
	projectId: string,
	attachProjectDocumentBody: BodyType<AttachProjectDocumentBody>,
	options?: SecondParameter<typeof customInstance>,
	signal?: AbortSignal,
) => {
	const formData = new FormData();
	if (attachProjectDocumentBody.file !== undefined) {
		formData.append(`file`, attachProjectDocumentBody.file);
	}

	if (attachProjectDocumentBody.category !== undefined) {
		formData.append(`category`, attachProjectDocumentBody.category);
	}

	if (attachProjectDocumentBody.documentDate !== undefined) {
		formData.append(`documentDate`, attachProjectDocumentBody.documentDate);
	}

	if (attachProjectDocumentBody.validUntil !== undefined) {
		formData.append(`validUntil`, attachProjectDocumentBody.validUntil);
	}

	if (attachProjectDocumentBody.note !== undefined) {
		formData.append(`note`, attachProjectDocumentBody.note);
	}

	return customInstance<ProjectDocumentAttached>(
		{
			url: `/api/projects/${projectId}/documents`,
			method: "POST",
			headers: { "Content-Type": "multipart/form-data" },
			data: formData,
			signal,
		},
		options,
	);
};

